export const MCNP_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/mcnp-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getMcnpStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(MCNP_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
